let view = new JavaAdapter(android.view.View, {
onDraw: function (canvas) {
// 调用父类View的onDraw
this.super$onDraw(canvas); 
canvas.drawRect(500, 500, 1000, 1000, paint);
},
// activity为android.view.View的构造函数参数
}, activity);

$ui.container.addView(view);

