// 添加一个每周日下午1点13分运行的定时任务，循环运行5次脚本，间隔5000毫秒
let task = $work_manager.addWeeklyTask({
path: jsPath,
time: 1624252440000,
daysOfWeek: ['sunday'],
delay: 0,
loopTimes: 5,
interval: 5000
});
// 按脚本路径查找定时任务
