首先，在代码中导入所需的类。在这个例子中，我们需要使用 TelephonyManager、Intent 和 IntentFilter 类。
importClass(android.telephony.TelephonyManager);
importClass(android.content.Intent);
importClass(android.content.IntentFilter);

接下来，创建一个 IntentFilter 对象，并添加要监听的动作。在这个例子中，我们将监听电话状态变化的动作 android.intent.action.PHONE_STATE。
let filter = new IntentFilter();
filter.addAction("android.intent.action.PHONE_STATE");

然后，我们将创建一个广播接收器。通过继承 android.content.BroadcastReceiver 类，并重写 onReceive 方法来实现广播接收器。
在 onReceive 方法中，我们可以根据接收到的 Intent 对象进行相应的逻辑处理。在这个例子中，我们打印出广播的动作和电话状态。
var myBroadcastReceiver = new JavaAdapter(android.content.BroadcastReceiver, {
onReceive: function(context, intent) {
let action = intent.getAction();
if ('android.intent.action.PHONE_STATE' == action) {
let state = intent.getStringExtra(TelephonyManager.EXTRA_STATE);
switch (state) {
case 'IDLE':
console.log('挂断电话');
break;
case 'RINGING':
console.log('电话正在响铃');
break;
case 'OFFHOOK':
console.log('电话处于通话状态');
break;
default:
break;
}
}
}
});

最后，我们可以在一个循环中保持代码的执行，以便持续监听广播消息。在这个例子中，我们使用 setInterval 函数来实现每秒执行一次的功能。
setInterval(() => {
// 保持代码执行
}, 1000);

在代码执行结束时，我们需要取消注册广播接收器，以释放资源，否则会导致内存泄漏。
$events.on('exit', () => {
context.unregisterReceiver(myBroadcastReceiver);
});

/**
* 注册电话状态广播接收器
*/
function registerPhoneStateReceiver() {
importClass(android.telephony.TelephonyManager);
importClass(android.content.Intent);
importClass(android.content.IntentFilter);

let filter = new IntentFilter();
filter.addAction("android.intent.action.PHONE_STATE"); // 监听电话状态变化

let myBroadcastReceiver = new JavaAdapter(android.content.BroadcastReceiver, {
/**
* 接收广播回调函数
* @param {android.content.Context} context 广播上下文对象
* @param {Object} intent 广播意图对象
*/
onReceive: function(context, intent) {
let action = intent.getAction();
if ('android.intent.action.PHONE_STATE' == action) {
// 监听来电状态
let state = intent.getStringExtra(TelephonyManager.EXTRA_STATE);
switch(state) {
case 'IDLE':
// 挂断电话
console.log('挂断电话');
break;
case 'RINGING':
// 电话正在响铃
console.log('电话正在响铃');
break;
case 'OFFHOOK':
// 电话处于通话状态
console.log('电话处于通话状态');
break;
default:
break;
}
}
}
});
context.registerReceiver(myBroadcastReceiver, filter); // 注册广播接收器
$events.on('exit', () => {
// 取消注册广播接收器，否则会导致内存泄露
context.unregisterReceiver(myBroadcastReceiver);
});
}

registerPhoneStateReceiver();

setInterval(() => {
// 用于脚本保活，ui界面不需要
}, 1000);

首先，我们可以通过跳转拨号界面的方式实现电话拨打功能。这种方式不需要额外的权限，用户需要手动点击拨打按钮来完成拨号操作。
以下是使用Auto.js实现跳转拨号界面的示例代码：
var Intent = {
action: "DIAL",
data: "tel:10000"
};

app.startActivity(Intent);

在这段代码中，我们创建了一个名为Intent的对象，并设置了两个属性：action和data。其中，action的值为DIAL，表示拨号动作；data的值为tel:10000，表示要拨打的电话号码是10000。通过调用app.startActivity(Intent)方法，我们可以在Auto.js应用中启动系统的电话拨号界面，并自动填充电话号码为10000。

另一种实现电话拨打功能的方式是直接拨号。但是，这种方式需要在应用中添加相应的权限声明。
以下是使用Auto.js实现直接拨号的示例代码：
var Intent = {
action: "android.intent.action.CALL",
data: "tel:10000"
};

app.startActivity(Intent);

与跳转拨号界面不同，这段代码中的Intent对象设置了两个属性：action和data。其中，action的值为android.intent.action.CALL，表示进行呼叫操作；data的值为tel:10000，表示要拨打的电话号码是10000。
在中使用直接拨号方式时：
安卓 需要在AndroidManifest.xml文件中添加相应的权限声明：

<uses-permission android:name="android.permission.CALL_PHONE" />

Autojs 需要在project.json文件中添加相应的权限声明：

{
"permissionConfig": {
"manifestPermissions": [
"android.permission.CALL_PHONE"
]
}
}

- 建议配置启动时自动申请权限:

{
"permissionConfig": {
"manifestPermissions": [
"android.permission.CALL_PHONE"
],
"requestListOnStartup": [
"android.permission.CALL_PHONE"
]
}
}

这样才能确保Auto.js应用在运行时具有拨号权限。

首先，我们需要导入一些Android图形类，包括Color、GradientDrawable、Orientation、ShapeDrawable和RoundRectShape。这些类将用于创建和配置我们的渐变背景对象。
importClass(android.graphics.Color);
importClass(android.graphics.drawable.GradientDrawable);
importClass(android.graphics.drawable.GradientDrawable.Orientation);
importClass(android.graphics.drawable.ShapeDrawable)
importClass(android.graphics.drawable.shapes.RoundRectShape)
importClass(android.graphics.drawable.LayerDrawable)

你可以根据自己的需求调用createBorderedDrawable函数并传入自定义的参数来创建渐变背景对象。以下是一个使用示例：
"ui";
importClass(android.graphics.Color);
importClass(android.graphics.drawable.GradientDrawable);
importClass(android.graphics.drawable.GradientDrawable.Orientation);

$ui.layout(
<vertical gravity="center" padding="20">
<text id="text1" text="示例" textSize="22" padding="5 10"/>
<button id="button1" text="按钮" marginTop="10"/>
<input id="input1" text="输入框" marginTop="10" padding="5 10"/>
<checkbox id="checkbox1" text="复选框" marginTop="10" />
<radio id="radio1" text="单选框1" marginTop="10"/>
</vertical>
);
let borderedDrawable = createBorderedDrawable({
rgb: '#ff0000',
cornerRadius: 20,
alpha: 200
});
$ui['text1'].setBackground(borderedDrawable)
$ui['button1'].setBackground(borderedDrawable)
$ui['input1'].setBackground(borderedDrawable)
$ui['checkbox1'].setBackground(borderedDrawable)
$ui['radio1'].setBackground(borderedDrawable)



/**
* 创建一个带有边框和圆角的 GradientDrawable 对象。
*
* @param {Object} [args] - 函数参数对象。
* @param {string} [args.rgb='#eeeeee'] - 边框颜色，默认为灰色（#eeeeee）。
* @param {number} [args.cornerRadius=10] - 圆角半径，默认为 10 像素。
* @param {number} [args.alpha=255] - 填充颜色透明度，取值范围是 0 到 255，默认为不透明（255）。
* @return {GradientDrawable} 返回一个创建好的 GradientDrawable 对象。
*/
function createBorderedDrawable(args) {
args = args || {}
args.rgb = args.rgb || '#eeeeee';
args.cornerRadius = args.cornerRadius || 10;
args.alpha = args.alpha || 255; // 注意：alpha 的取值范围是 0 到 255
let gradientDrawable = new GradientDrawable(); // 创建一个 GradientDrawable 对象
gradientDrawable.setStroke(2, colors.parseColor(args.rgb)); // 设置对象的边框宽度和颜色
gradientDrawable.setOrientation(GradientDrawable$Orientation.LEFT_RIGHT); // 设置对象的方向为左右
gradientDrawable.setCornerRadius(args.cornerRadius); // 设置对象的圆角半径
gradientDrawable.setAlpha(args.alpha); // 设置对象的填充颜色透明度
return gradientDrawable; // 返回创建的 GradientDrawable 对象
}

上述示例中，我们调用createBorderedDrawable函数，并传入了自定义的参数对象。我们设置了边框颜色为红色、圆角半径为20像素、填充颜色透明度为200。然后，将创建的borderedDrawable对象设置为某个View的背景。
使用以上方法，你可以根据需要创建出符合你期望效果的带有边框和圆角的渐变背景对象。希望本文对你有所帮助！

创建一个新的Auto.js脚本，在脚本中导入android.app.PendingIntent类并定义其他必要的变量。
importClass('android.app.PendingIntent');

var smsManager = android.telephony.SmsManager.getDefault();
var phoneNumber = "1234567890"; // 设置要发送短信的手机号码
var message = "Hello, World!"; // 设置要发送的短信内容

// 创建PendingIntent对象，用于接收发送和交付短信的结果
var sentIntent = PendingIntent.getBroadcast(context, 0, new Intent(), 0);
var deliveredIntent = PendingIntent.getBroadcast(context, 0, new Intent(), 0);

// 发送短信
smsManager.sendTextMessage(phoneNumber, null, message, sentIntent, deliveredIntent);

/**
* 发送短信
* @param {string} phoneNumber 接收短信的手机号码
* @param {string} message 要发送的短信内容
*/
function sendSMS(phoneNumber, message){
let smsManager = android.telephony.SmsManager.getDefault();

// 创建PendingIntent对象，用于接收发送和交付短信的结果
let sentIntent = android.app.PendingIntent.getBroadcast(context, 0, new Intent(), 0);
let deliveredIntent = android.app.PendingIntent.getBroadcast(context, 0, new Intent(), 0);

// 发送短信
smsManager.sendTextMessage(phoneNumber, null, message, sentIntent, deliveredIntent);
}
let phoneNumber = "1234567890"; // 设置要发送短信的手机号码
let message = "Hello, World!"; // 设置要发送的短信内容

sendSMS(phoneNumber, message);

