▸ queryIntentTasks(query?): Promise<Task[]>
通过脚本路径或Intent Action等条件查询意图任务。
示例
"nodejs";
const { queryIntentTasks, addBroadcastIntentTask } = require("work_manager");
async function main() {
const task = await addBroadcastIntentTask({
